def is_valid_slot(slot):
    # Split the slot string by '/'
    parts = slot.split('/')

    # Check if there are exactly 2 parts
    if len(parts) != 2:
        return False

    # Check if the first part is in the correct format (HH:MM)
    try:
        hours, minutes = map(int, parts[0].split(':'))
        if hours < 0 or hours >= 24 or minutes < 0 or minutes >= 60:
            return False
    except ValueError:
        return False

    # Check if the second part is in the correct format (R)
    if parts[1] != 'R':
        return False

    # Check if the minutes is a multiple of 15
    if minutes % 15 != 0:
        return False

    # Check if the time is within the valid range (05:00 to 23:30)
    if parts[0] >= '07' and parts[0] <= '23' and parts[1] >= '00' and parts[1] <= '30':
        return True

    # Check if the runway is 4 (short runway) and the time is before 12:00
    if parts[1] == '4' and parts[0] >= '12':
        return False

    return True
